save(471,dict(paragraphs=['Kallol Choudhury works across poetry, short fiction and translation. Sahitya Akademi published Samparka, his Bengali translation of Jayanta Mahapatra’s Relationship, in 2006. His English poetry collection Buddha on Planchette was published by Penprints in 2023; his publisher also records contributions of stories, translations and a folktale to Oxford University Press anthologies.','The two poems gathered here turn affection into a landscape of colour and touch. “The Bluish Splendour Of Your Eyes” moves between brightness and passing gloom, finding transformation in an artistic hand. In “In The Moonlight Soaked Meadow,” afternoon, dusk and river become ways of remembering a face. The river’s movement carries the tenderness that the speaker tries to hold.'],sources=[source('Sahitya Akademi — Bengali publications catalogue','https://sahitya-akademi.gov.in/publications/bengali.pdf',['Samparka by Jayanta Mahapatra, translated by Kallol Choudhury, first edition 2006; PDF page 7.']),source('Penprints — Buddha on Planchette','https://penprints.in/shop/product/buddha-on-planchette-by-kollol-choudhury/',['Poet, short-story writer and translator; book and Oxford anthology contributions.']),source('Google Books — Buddha on Planchette','https://books.google.com/books/about/Buddha_on_Planchette.html?id=QwPkEAAAQBAJ',['Penprints 2023 publication, ISBN 9788196417734; indexed terms include both local poem titles.'])],books=[dict(title='Buddha on Planchette',detail='English poetry · Penprints, 2023',url='https://penprints.in/shop/product/buddha-on-planchette-by-kollol-choudhury/')],identity_match='Specific Mahapatra translation matches capture; publisher biography and Google Books title terms match both local poems. Kallol/Kollol spelling variants documented, display retained.',poems_read=[dict(id=805,title='The Bluish Splendour Of Your Eyes',basis='Full English poem read; colour, gloom, artistic hand, philosopher’s stone and tenderness.'),dict(id=806,title='In The Moonlight Soaked Meadow',basis='Full English poem read; afternoon in dusk’s palms, river/face and moonlit meadow.')],limitations=['Book totals vary across dated sources; no count used.','Lapbah contribution remains author-interview supported but was not independently located in publisher contents; omitted from new prose.','International award claims omitted; no organizer confirmation.'],research_leads=[dict(url='https://epaper.thedailyguardian.com/media/2025-03/tdg_07_march.pdf',finding='Indexed author interview supports Lapbah and Sonbeel; direct PDF fetch failed, not needed for new narrative.')],next_action='Independent author/editor review; verify Lapbah contents before extending bibliography.'))
